package io.github.rebrowser.engine;
import static org.junit.Assert.*;
import org.junit.Test;
/** Original-session observation reducer only, NOT Android fullscreen/SDK completion. */
public final class NativeFullscreenObservationTest {
 @Test public void dispatchAndUnrelatedMetadataCannotSettleFullscreenBack(){SessionPresentation p=new SessionPresentation();p.fullScreen(true);long before=p.snapshot().reportedFullScreenSequence();assertFalse(SessionPresentation.nativeFullscreenExitObserved(before,p.snapshot()));p.title("still fullscreen");p.progress(90);p.location("https://www.baidu.com/");assertFalse(SessionPresentation.nativeFullscreenExitObserved(before,p.snapshot()));assertEquals(before,p.snapshot().reportedFullScreenSequence());}
 @Test public void onlyNewFalseNativeEventSettles(){SessionPresentation p=new SessionPresentation();p.fullScreen(true);long before=p.snapshot().reportedFullScreenSequence();p.fullScreen(true);assertFalse(SessionPresentation.nativeFullscreenExitObserved(before,p.snapshot()));p.fullScreen(false);assertTrue(SessionPresentation.nativeFullscreenExitObserved(before,p.snapshot()));}
 @Test public void oldFalseFrameAndInitialAbsenceAreNotExitReceipt(){SessionPresentation p=new SessionPresentation();assertFalse(SessionPresentation.nativeFullscreenExitObserved(0,p.snapshot()));p.fullScreen(false);SessionPresentation.Frame old=p.snapshot();p.fullScreen(true);long before=p.snapshot().reportedFullScreenSequence();assertFalse(SessionPresentation.nativeFullscreenExitObserved(before,old));assertFalse(SessionPresentation.nativeFullscreenExitObserved(before,null));}
 @Test public void retirementIsNotFakeNativeExit(){SessionPresentation p=new SessionPresentation();p.fullScreen(true);long before=p.snapshot().reportedFullScreenSequence();p.retire();assertFalse(p.snapshot().reportedFullScreen());assertFalse(SessionPresentation.nativeFullscreenExitObserved(before,p.snapshot()));}
 @Test public void immutableNativeFrameDoesNotChangeWithLaterSessionEvents(){SessionPresentation p=new SessionPresentation();p.fullScreen(true);SessionPresentation.Frame original=p.snapshot();p.fullScreen(false);assertTrue(original.reportedFullScreen());assertFalse(SessionPresentation.nativeFullscreenExitObserved(original.reportedFullScreenSequence(),original));assertTrue(SessionPresentation.nativeFullscreenExitObserved(original.reportedFullScreenSequence(),p.snapshot()));}
}
